pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        vm.startPrank(owner);
        try c.OpenToThePublic() { } catch { }
        vm.stopPrank();
        // If the caller is the owner (address(this)), the call succeeded;
        // otherwise it reverted. The invariant only makes a claim about a
        // successful call made by the owner, which is exactly the case when
        // owner == address(this). In that case, openToPublic must become true.
        // The buggy version sets it to false, so the assertion fails.
        if (owner == address(this)) {
            assertTrue(c.openToPublic());
        } else {
            // Not the owner, so the call reverted and openToPublic must be unchanged (false).
            assertTrue(!c.openToPublic());
        }
    }
}

